mapper.sql:
ROUND(
  6371000 * 2 * ASIN(
    SQRT(
      POW(SIN(RADIANS((latitude - #{latitude}) / 2)), 2)
      + COS(RADIANS(#{latitude}))
      * COS(RADIANS(latitude))
      * POW(SIN(RADIANS((longitude - #{longitude}) / 2)), 2)
    )
  )
)

mapper.select:
SELECT
FROM pois p JOIN poi_categories c ON c.id = p.category_id WHERE p.status = 1 AND p.longitude IS NOT NULL AND p.latitude IS NOT NULL AND COALESCE(p.area_code, '') != 'route' AND COALESCE(p.area_code, '') != 'campus_summary'
AND p.name LIKE CONCAT('%', #{keyword}, '%')
AND c.code = #{category}
AND p.place_group_id = #{placeGroupId}
ORDER BY p.place_group_id ASC, p.hotness DESC, p.id ASC LIMIT 300

SELECT

FROM pois p
JOIN poi_categories c ON c.id = p.category_id
WHERE p.id = #{id}
  AND p.status = 1

    AND p.place_group_id = #{placeGroupId}

SELECT
FROM pois p JOIN poi_categories c ON c.id = p.category_id WHERE p.status = 1 AND p.name = #{name}
AND p.place_group_id = #{placeGroupId}
ORDER BY p.place_group_id ASC, p.hotness DESC, p.id ASC LIMIT 1

SELECT e.id, e.from_poi_id AS fromPoiId, e.to_poi_id AS toPoiId, e.distance_m AS distanceM, e.duration_min AS durationMin, e.congestion_factor AS congestionFactor, e.is_indoor AS indoor, e.transport_type AS transportType, e.description FROM route_edges e JOIN pois fp ON fp.id = e.from_poi_id JOIN pois tp ON tp.id = e.to_poi_id WHERE fp.status = 1 AND tp.status = 1
AND fp.place_group_id = #{placeGroupId} AND tp.place_group_id = #{placeGroupId}
AND (e.is_indoor = 1 OR e.transport_type = 'indoor')

SELECT
FROM pois p JOIN poi_categories c ON c.id = p.category_id WHERE p.id IN ( SELECT from_poi_id FROM route_edges UNION SELECT to_poi_id FROM route_edges ) AND p.status = 1
AND p.place_group_id = #{placeGroupId}
